if (navigator.userAgent.includes('Firefox')) {
  document.documentElement.classList.add('ua-firefox');
} else if (navigator.userAgent.includes("Safari") && !navigator.userAgent.includes("Chrome") && !navigator.userAgent.includes("Chromium")) {
  document.documentElement.classList.add('ua-safari');
}

document.addEventListener('DOMContentLoaded', () => {
  // set up tom select for search inputs (but bail early if no search inputs are found)
  const searchInputs = ['#search-input', '#search-input-header-mobile', '#search-input-header-desktop'];
  if (!document.querySelector(searchInputs.join(', '))) return;

  // get the selected options from the URL params
  const urlParams = new URLSearchParams(window.location.search);
  const selectedOptions = urlParams.get('q')?.split(',').filter(Boolean) || [];

  // set up tom select config
  const config = {
    options: window.schoolList.concat(window.sportList).concat(selectedOptions).map(option => ({ text: option, value: option })),
    openOnFocus: false,
    closeAfterSelect: true,
    addPrecedence: true,
    create: true,
    maxOptions: 20,
    items: selectedOptions,
    score: function (search) {
      // Ensure broader match handling but still prioritize startsWith
      return function (item) {
        const text = item.text.toLowerCase();
        const query = search.toLowerCase();

        if (text.startsWith(query)) return 1; // Prioritize matches at the beginning
        if (text.includes(query)) return 0.5; // Include partial matches elsewhere
        return 0; // Exclude non-matches
      };
    },
    render: {
      option: function (data, escape) {
        return '<div>' + escape(data.text) + '</div>';
      },
      item: function (data, escape) {
        return '<div>' + escape(data.text) + '</div>';
      },
      option_create: function (data, escape) {
        return '<div class="create"><strong>' + escape(data.input) + '</strong></div>';
      },
      no_results: function (data, escape) {
        return '<div class="no-results">No results found for "' + escape(data.input) + '"</div>';
      },
      not_loading: function (data, escape) {
        // no default content
      },
      optgroup: function (data) {
        let optgroup = document.createElement('div');
        optgroup.className = 'optgroup';
        optgroup.appendChild(data.options);
        return optgroup;
      },
      optgroup_header: function (data, escape) {
        return '<div class="optgroup-header">' + escape(data.label) + '</div>';
      },
      loading: function (data, escape) {
        return '<div class="spinner"></div>';
      },
      dropdown: function () {
        return '<div></div>';
      }
    }
  };
  searchInputs.forEach(input => {
    if (document.querySelector(input)) {
      new TomSelect(input, config);
    }
  });
});
